const p = $input.first().json.body || $input.first().json;
const action = p.action || "";
const pr = p.pull_request || {};
const repo = p.repository?.full_name || "";
if (!["opened", "synchronize", "reopened"].includes(action) || !repo || !pr.number) {
  return [];
}
return [{
  json: {
    repo,
    prNumber: pr.number,
    title: pr.title || "",
    author: pr.user?.login || "unknown",
    filesUrl: `https://api.github.com/repos/${repo}/pulls/${pr.number}/files?per_page=30`,
    commentUrl: `https://api.github.com/repos/${repo}/issues/${pr.number}/comments`,
  }
}];

const meta = $('Filter Opened/Sync PRs').first().json;
const files = $input.all().map((i) => i.json).flat();
const patchSummary = files.slice(0, 12).map((f) => `FILE: ${f.filename} (+${f.additions}/-${f.deletions})\n${String(f.patch || '').slice(0, 1200)}`).join('\n---\n').slice(0, 10000);
return [{ json: { ...meta, patchSummary } }];

const meta = $('Filter Opened/Sync PRs').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
let ai = { riskLevel: 'LOW', markdownComment: 'No critical issues detected.' };
try { ai = { ...ai, ...JSON.parse(raw) }; } catch {}
return [{ json: { commentUrl: meta.commentUrl, body: `### 🛡️ Automated PR Security Review (Risk: **${ai.riskLevel}**)\n\n${ai.markdownComment}` } }];
